package com.synexia.m3.bootstrap; import java.nio.file.*; import java.security.*; import java.util.*; import org.openrewrite.*; public final class M3BootstrapTaskRecipe extends Recipe { public String getDisplayName(){return "M3 bootstrap task-crate recipe-first lane";} public String getDescription(){return "Exact task-crate SHA-256 gate followed by read-only inventory.";} public Set<String> getTags(){return Set.of("synexia","m3","recipe-first","task-crate");} public int maxCycles(){return 1;} public java.util.List<Recipe> getRecipeList(){verify();return java.util.List.of(new M3BootstrapInventoryRecipe());} public boolean directTargetFileMutationAuthority(){return false;} static void verify(){String f=System.getProperty("m3.llm.taskCrateFile","").strip(),e=System.getProperty("m3.llm.taskCrateRoot","").strip().toLowerCase(Locale.ROOT); if(f.isEmpty()||!e.matches("[0-9a-f]{64}"))throw new IllegalArgumentException("M3 task-crate properties required"); Path p=Path.of(f).toAbsolutePath().normalize(); try{if(Files.isSymbolicLink(p)||!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS))throw new IllegalStateException("M3_TASK_CRATE_NOT_REGULAR"); byte[] b=Files.readAllBytes(p); if(b.length<1||b.length>4*1024*1024)throw new IllegalStateException("M3_TASK_CRATE_SIZE"); String a=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b)); if(!a.equals(e))throw new IllegalStateException("M3_TASK_CRATE_SHA256");}catch(java.io.IOException|NoSuchAlgorithmException x){throw new IllegalStateException(x);}} }